mapper.select:
select rno.id, rno.return_notice_order_no, rno.status,rno.sku_count,rno.return_type, rno.return_why, rno.take_effect_time, rno.return_deadline,rno.remark, rno.biz_org_code, rno.creator, rno.create_time, rno.updater, rno.update_time, rno.is_delete, case when (select odr.return_notice_order_id from ord_dis_return odr where odr.store_code = #{storeCode,jdbcType=VARCHAR} and odr.return_notice_order_id = rno.id and odr.is_delete = 0 limit 1) > 0 then 1 else 0 END as isReturn from ord_dis_return_notice rno where 1=1
and rno.return_notice_order_no = #{returnNoticeOrderNo}
and exists (select 1 from ord_dis_return_notice_store rns where rno.id = rns.return_notice_order_id and rns.store_code = #{storeCode})
and exists (select 1 from ord_dis_return_notice_goods rng where rno.id = rng.return_notice_order_id and rng.goods_code = #{goodsCode})
and rno.biz_org_code = #{bizOrgCode}
and rno.status = #{status}
and rno.create_time between #{beginTime} and #{endTime}
and rno.take_effect_time between #{takeEffectBeginTime} and #{takeEffectEndTime}
and rno.creator like concat('%', #{creator}, '%')
group by rno.id

select

from
ord_dis_return_notice


        and is_delete = #{isDelete}


        and status = #{status,jdbcType=VARCHAR}



        and take_effect_time <= #{takeEffectTime,jdbcType=TIMESTAMP}
        and return_deadline >=#{takeEffectTime,jdbcType=TIMESTAMP}

select g.goods_code, g.bar_code, g.goods_name, g.goods_image,s.qty from ord_dis_return_notice_goods g
inner JOIN ord_dis_return_notice_store s on s.return_notice_order_id = g.return_notice_order_id  and s.return_notice_goods_id = g.id
where g.return_notice_order_id = #{returnNoticeOrderId} and s.store_code = #{storeCode}
